  status: { erforscht: 'Erforscht', aktiv: 'Wird gerade erforscht', moeglich: 'Kann jetzt erforscht werden', gesperrt: 'Noch nicht erreichbar', gebaut: (v) => `Gebaut von ${v}`, imBau: (v) => `Im Bau bei ${v}`, frei: 'Noch von niemandem gebaut' },
